package br.com.netwatch;

import java.sql.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

public final class Store {
    public record SwitchRow(long id,String name,String model,String address,String location,String status,String checkedAt){}
    private Connection db;
    public Store() {}
    public void initialize(){try{java.nio.file.Path folder=java.nio.file.Path.of(System.getProperty("user.home"),".netwatch");java.nio.file.Files.createDirectories(folder);db=DriverManager.getConnection("jdbc:sqlite:"+folder.resolve("netwatch.db"));try(Statement s=db.createStatement()){s.execute("PRAGMA foreign_keys=ON");s.execute("CREATE TABLE IF NOT EXISTS switches(id INTEGER PRIMARY KEY,name TEXT NOT NULL,model TEXT,address TEXT,location TEXT,status TEXT NOT NULL,checked_at TEXT)");s.execute("CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,switch_id INTEGER,old_state TEXT,new_state TEXT,at TEXT NOT NULL,message TEXT,FOREIGN KEY(switch_id) REFERENCES switches(id))");s.execute("CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,at TEXT NOT NULL,action TEXT NOT NULL,details TEXT)");}if(switches().isEmpty())seed();}catch(Exception e){throw new IllegalStateException("Falha ao iniciar banco local",e);}}
    private void seed() throws SQLException {insert(List.of("Core-01","Demo / Virtual","192.0.2.10","Lab • Andar 1"));insert(List.of("Acesso-02","Demo / Virtual","192.0.2.11","Lab • Andar 2"));insert(List.of("Acesso-03","Demo / Virtual","192.0.2.12","Lab • Andar 2"));transition(1,"UP");transition(2,"DOWN");}
    public List<SwitchRow> switches(){List<SwitchRow> out=new ArrayList<>();try(Statement s=db.createStatement();ResultSet r=s.executeQuery("SELECT * FROM switches ORDER BY name")){while(r.next())out.add(new SwitchRow(r.getLong("id"),r.getString("name"),r.getString("model"),r.getString("address"),r.getString("location"),r.getString("status"),Objects.toString(r.getString("checked_at"),"—")));return out;}catch(SQLException e){throw new IllegalStateException(e);}}
    public void insert(List<String> v){try(PreparedStatement p=db.prepareStatement("INSERT INTO switches(name,model,address,location,status) VALUES(?,?,?,?, 'UNKNOWN')")){for(int i=0;i<4;i++)p.setString(i+1,v.get(i));p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
    public void transition(long id,String next){try{String old="UNKNOWN";try(PreparedStatement q=db.prepareStatement("SELECT status FROM switches WHERE id=?")){q.setLong(1,id);try(ResultSet r=q.executeQuery()){if(r.next())old=r.getString(1);}}String now=Instant.now().toString();try(PreparedStatement p=db.prepareStatement("UPDATE switches SET status=?,checked_at=? WHERE id=?")){p.setString(1,next);p.setString(2,now);p.setLong(3,id);p.executeUpdate();}if(!old.equals(next))try(PreparedStatement p=db.prepareStatement("INSERT INTO events(switch_id,old_state,new_state,at,message) VALUES(?,?,?,?,?)")){p.setLong(1,id);p.setString(2,old);p.setString(3,next);p.setString(4,now);p.setString(5,"Transição simulada");p.executeUpdate();}}catch(SQLException e){throw new IllegalStateException(e);}}
    public long count(String state){try(PreparedStatement p=db.prepareStatement("SELECT COUNT(*) FROM switches WHERE status=?")){p.setString(1,state);try(ResultSet r=p.executeQuery()){return r.getLong(1);}}catch(SQLException e){throw new IllegalStateException(e);}}
    public long eventCount(){try(Statement s=db.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM events")){return r.getLong(1);}catch(SQLException e){throw new IllegalStateException(e);}}
    long auditCount(){try(Statement s=db.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM audit")){return r.getLong(1);}catch(SQLException e){throw new IllegalStateException(e);}}
    public void clearLogs(){try{db.setAutoCommit(false);try(Statement s=db.createStatement()){s.executeUpdate("DELETE FROM events");}try(PreparedStatement p=db.prepareStatement("INSERT INTO audit(at,action,details) VALUES(?,?,?)")){p.setString(1,Instant.now().toString());p.setString(2,"CLEAR_LOG");p.setString(3,"Eventos locais removidos pelo usuário");p.executeUpdate();}db.commit();}catch(SQLException e){try{db.rollback();}catch(SQLException ignored){}throw new IllegalStateException(e);}finally{try{db.setAutoCommit(true);}catch(SQLException ignored){}}}
    public String report(DateTimeFormatter fmt){StringBuilder b=new StringBuilder("==================================================\r\nNETWATCH - RELATÓRIO DE MONITORAMENTO\r\n==================================================\r\n");b.append("Data de geração: ").append(LocalDateTime.now().format(fmt)).append("\r\nPeríodo: todo o histórico local\r\nModo: demonstração\r\n\r\nRESUMO\r\n--------------------------------------------------\r\nTotal de switches: ").append(switches().size()).append("\r\nSwitches UP: ").append(count("UP")).append("\r\nSwitches DOWN: ").append(count("DOWN")).append("\r\nEstado desconhecido: ").append(count("UNKNOWN")).append("\r\n\r\nHISTÓRICO DE TRANSIÇÕES\r\n--------------------------------------------------\r\n");try(Statement s=db.createStatement();ResultSet r=s.executeQuery("SELECT e.at,s.name,e.old_state,e.new_state,e.message FROM events e LEFT JOIN switches s ON s.id=e.switch_id ORDER BY e.at DESC")){while(r.next())b.append(r.getString(1)).append(" | ").append(r.getString(2)).append(" | ").append(r.getString(3)).append(" → ").append(r.getString(4)).append(" | ").append(r.getString(5)).append("\r\n");}catch(SQLException e){throw new IllegalStateException(e);}b.append("\r\nOBSERVAÇÕES\r\n--------------------------------------------------\r\nEstados são simulados; não foram feitas conexões de rede. Não há dados suficientes para estimar disponibilidade histórica.\r\n\r\n==================================================\r\nFIM DO RELATÓRIO\r\n");return b.toString();}
    public void close(){try{if(db!=null)db.close();}catch(SQLException ignored){}}
}
